   tables.append([[(txt(cell),[(etree.QName(p).localname,dict(p.attrib))for p in cell.findall('w:tcPr/*',ns)if etree.QName(p).localname in['gridSpan','vMerge','shd']])for cell in row.findall('w:tc',ns)]for row in t.findall('w:tr',ns)])
